import {Injectable,Injector} from '@angular/core';import {HttpInterceptor,HttpRequest,HttpHandler} from '@angular/common/http';import {Router} from '@angular/router';import {catchError,throwError} from 'rxjs';
@Injectable()export class LegalInterceptor implements HttpInterceptor{constructor(private injector:Injector){}intercept(req:HttpRequest<any>,next:HttpHandler){return next.handle(req).pipe(catchError(err=>{if(err.status===428&&err.error?.error==='legal_acceptance_required'){const router=this.injector.get(Router);if(!router.url.startsWith('/account/accept-terms'))void router.navigate(['/account/accept-terms'],{queryParams:{role:err.error.requiredRole||(/\/api\/owner/.test(req.url)?'assetOwner':/\/api\/concierge/.test(req.url)?'concierge':'customer'),returnUrl:router.url}});}return throwError(()=>err);}));}}
