  display: block;
  background: #f8f6f1;
  color: #17313e;
}

.listings-shell {
  max-width: 1120px;
  margin: auto;
  padding: 28px 20px;
}

header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
}

header p {
  max-width: 780px;
  line-height: 1.5;
}

section, article {
  background: white;
  border: 1px solid #dce3e6;
  border-radius: 14px;
  padding: 24px;
  margin: 20px 0;
}

.fields {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 16px;
}

label {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-bottom: 14px;
}

input, textarea, select {
  padding: 12px;
  border: 1px solid #b6c7cf;
  border-radius: 8px;
  font: inherit;
}

textarea {
  min-height: 100px;
}

button, .actions a {
  padding: 10px 14px;
  background: #12506a;
  color: white;
  border: 0;
  border-radius: 8px;
  text-decoration: none;
  cursor: pointer;
}

button:disabled {
  opacity: 0.5;
  cursor: wait;
}

.actions, nav {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 10px;
}

fieldset {
  border: 0;
  padding: 0;
  min-width: 0;
}

.error {
  background: #fff0ed;
  color: #862c20;
  padding: 15px;
  border-radius: 8px;
}

@media (max-width: 600px) {
  header {
    align-items: start;
    flex-direction: column;
  }
  section, article {
    padding: 16px;
  }
}
.reservation-warning {
  background: #fff6dd;
  border: 1px solid #d5b257;
  border-radius: 8px;
  padding: 16px;
  margin: 16px 0;
  color: #513b14;
}

.acknowledgement {
  display: flex;
  flex-direction: row;
  align-items: flex-start;
  gap: 10px;
}

.acknowledgement input {
  margin-top: 4px;
}

button.danger {
  background: #9a3027;
}

form button + button {
  margin-left: 8px;
}

#listing-editor {
  scroll-margin-top: 150px;
}

.onboarding {
  padding: 20px;
  margin: 20px 0;
  background: #edf6f5;
  border: 1px solid #bcd7d4;
  border-radius: 16px;
}

.onboarding li {
  margin: 8px 0;
  list-style: none;
}

.onboarding ul {
  padding: 0;
}

.wizard {
  max-width: 900px;
  margin: 28px auto;
  scroll-margin-top: 150px;
  outline-offset: 5px;
}

.wizard .fields {
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 20px;
}

.wizard h3 {
  margin: 28px 0 16px;
}

.wizard textarea {
  min-height: 140px;
}

.wizard small, .muted {
  color: #526976;
  line-height: 1.5;
}

.steps {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  margin: 24px 0;
  gap: 8px;
}

.steps button {
  background: #edf2f3;
  color: #36515e;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
}

.steps button.current {
  background: #12506a;
  color: white;
}

.steps span {
  font-weight: bold;
}

.steps button:disabled {
  cursor: default;
  opacity: 0.65;
}

.quiet, .actions .secondary {
  background: #edf2f3;
  color: #17313e;
}

.optional {
  padding: 14px 0;
  border-bottom: 1px solid #e0e7e9;
}

.optional summary, .more-actions summary {
  cursor: pointer;
  font-weight: 600;
}

.optional label {
  margin-top: 14px;
}

.checkbox {
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: 10px;
}

.checkbox input {
  width: auto;
}

.upload-zone {
  padding: 26px;
  border: 2px dashed #a1bec9;
  border-radius: 14px;
  background: #f5fafb;
  cursor: pointer;
}

.photo-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(170px, 1fr));
  gap: 16px;
}

.photo-grid figure {
  margin: 0;
  border: 1px solid #dce3e6;
  border-radius: 12px;
  overflow: hidden;
}

.photo-grid img {
  width: 100%;
  height: 150px;
  object-fit: cover;
}

.photo-grid figcaption {
  padding: 8px 12px;
  font-weight: 600;
}

.photo-actions {
  display: flex;
  gap: 4px;
  padding: 8px;
}

.photo-actions button {
  padding: 7px;
}

.danger-text {
  color: #9a3027 !important;
}

.wizard-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  border-top: 1px solid #dce3e6;
  margin-top: 28px;
  padding-top: 20px;
}

.subscription-note, .subscription-panel {
  background: #f1f7f7;
  border-radius: 12px;
  padding: 18px;
  margin-top: 18px;
}

.list-toolbar {
  justify-content: space-between;
  margin: 24px 0;
}

.status {
  background: #eef4f5;
  padding: 8px 12px;
  border-radius: 20px;
}

.more-actions {
  position: relative;
}

.more-actions summary {
  padding: 10px 14px;
}

.more-actions > div {
  position: absolute;
  z-index: 10;
  right: 0;
  min-width: 230px;
  padding: 10px;
  display: grid;
  gap: 4px;
  background: white;
  border: 1px solid #dce3e6;
  box-shadow: 0 8px 24px rgba(23, 49, 62, 0.1254901961);
  border-radius: 12px;
}

.more-actions a, .more-actions button {
  background: white;
  color: #17313e;
  text-align: left;
  display: block;
}

.more-actions a:hover, .more-actions button:hover {
  background: #edf2f3;
}

.listings-shell > article {
  position: relative;
}

.page-header h1 {
  margin-top: 0;
}

.wizard label input, .wizard label select {
  min-width: 0;
  max-width: 100%;
  box-sizing: border-box;
}

@media (max-width: 650px) {
  .wizard .fields {
    grid-template-columns: 1fr;
  }
  .steps button {
    font-size: 13px;
    padding: 10px 5px;
    gap: 5px;
  }
  .wizard header {
    flex-direction: row;
  }
  .more-actions > div {
    right: auto;
    left: 0;
  }
  .actions {
    gap: 8px;
  }
}
.prefix-picker {
  margin: 1.5rem 0;
  padding: 1rem;
  border: 1px solid #c7d8db;
  border-radius: 12px;
}

.prefix-option {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  margin: 0.5rem 0;
}

.prefix-option input {
  width: auto;
}

.prefix-picker input.prefix-invalid {
  border: 2px solid #b42318 !important;
  background: #fff5f5;
  color: #8a1c13;
}

.prefix-picker input.prefix-invalid:focus {
  outline: 2px solid #b42318;
  outline-offset: 2px;
}

.prefix-error {
  color: #b42318;
  font-weight: 600;
