  display: block;
}

.platform-shell {
  display: flex;
  flex-direction: column;
  min-height: 100vh;
  min-height: 100dvh;
  background: #f8f6f1;
  color: #173b36;
  font-family: Inter, "Segoe UI", Arial, sans-serif;
}

.platform-header {
  position: sticky;
  top: 0;
  z-index: 30;
  background: #f8f6f1;
  border-bottom: 1px solid #dce5df;
}

.platform-header-inner {
  max-width: 1200px;
  margin: auto;
  padding: 20px 24px;
  display: flex;
  align-items: center;
  gap: 24px;
  flex-wrap: wrap;
}

.platform-brand {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: #173b36;
  text-decoration: none;
  font-weight: 800;
  font-size: 26px;
  letter-spacing: -1px;
}

.brand-mark {
  padding: 7px;
  background: #173b36;
  color: #e3edb1;
  border-radius: 11px;
  font-size: 17px;
  letter-spacing: 0;
}

.brand-dot {
  color: #829d3b;
}

.platform-nav {
  display: flex;
  align-items: center;
  gap: 22px;
  flex-wrap: wrap;
  margin-left: auto;
}

.platform-nav a, .platform-footer nav a {
  font-size: 13px;
  color: #173b36;
  text-decoration: none;
  padding: 8px 0;
}

.platform-nav a.active {
  border-bottom: 2px solid #7c9650;
  font-weight: 700;
}

.platform-controls {
  display: flex;
  align-items: center;
  gap: 10px;
}

.platform-controls select {
  font: inherit;
  font-size: 12px;
  background: transparent;
  border: 1px solid #c4d1c5;
  border-radius: 8px;
  padding: 8px;
  color: #173b36;
}

.platform-account {
  position: relative;
}

.platform-account summary {
  font-size: 13px;
  cursor: pointer;
  padding: 9px;
}

.account-options {
  position: absolute;
  right: 0;
  top: 38px;
  min-width: 190px;
  padding: 8px;
  background: white;
  border: 1px solid #dce5df;
  border-radius: 12px;
  box-shadow: 0 12px 28px rgba(23, 59, 54, 0.1019607843);
}

.account-options button {
  display: block;
  width: 100%;
  padding: 12px;
  text-align: left;
  border: 0;
  background: transparent;
  color: #173b36;
  font: inherit;
  font-size: 13px;
  cursor: pointer;
}

.account-options button:hover {
  background: #eef1e8;
}

.auth-button {
  border: 0;
  background: transparent;
  color: #173b36;
  font: inherit;
  font-size: 12px;
  padding: 9px;
  cursor: pointer;
}

.create-account {
  border: 1px solid #173b36;
  border-radius: 100px;
}

.platform-content {
  flex: 1;
  min-width: 0;
  outline: none;
}

.platform-footer {
  width: 100%;
  max-width: 1200px;
  box-sizing: border-box;
  margin: 32px auto 0;
  padding: 30px 24px;
  border-top: 1px solid #dce5df;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 25px;
}

.footer-brand {
  font-size: 23px;
  gap: 0;
}

.platform-footer p, .platform-footer small {
  font-size: 12px;
  color: #64776f;
  line-height: 1.7;
}

.platform-footer nav {
  display: flex;
  gap: 24px;
  flex-wrap: wrap;
}

.platform-error {
  margin: 15px auto;
  padding: 14px;
  max-width: 1120px;
  background: #fff0ed;
  color: #862c20;
  border-radius: 8px;
}

.sr-only, .skip-link {
  position: absolute;
  height: 1px;
  width: 1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
}

.skip-link:focus {
  position: fixed;
  top: 5px;
  left: 5px;
  width: auto;
  height: auto;
  clip: auto;
  z-index: 40;
  background: white;
  color: #173b36;
  padding: 12px;
}

a:focus-visible, button:focus-visible, summary:focus-visible, select:focus-visible {
  outline: 3px solid #7fac61;
  outline-offset: 3px;
}

button:disabled {
  opacity: 0.5;
  cursor: wait;
}

@media (max-width: 900px) {
  .platform-nav {
    order: 3;
    width: 100%;
    margin: 0;
    gap: 20px;
  }
  .platform-controls {
    margin-left: auto;
  }
  .platform-header-inner {
    gap: 10px 20px;
    padding: 16px 20px;
  }
  .platform-footer {
    align-items: start;
    flex-direction: column;
  }
}
@media (max-width: 480px) {
  .platform-brand {
    font-size: 22px;
  }
  .brand-mark {
    display: none;
  }
  .platform-nav {
    gap: 14px;
  }
  .platform-nav a {
    font-size: 12px;
  }
  .platform-controls {
    gap: 3px;
  }
  .auth-button {
    font-size: 11px;
    padding: 7px;
  }
  .platform-footer nav {
    gap: 16px;
  }
}
.platform-controls {
  margin-left: auto;
}

.account-identity {
  display: flex;
  flex-direction: column;
  text-align: right;
  max-width: 240px;
  font-size: 13px;
  overflow-wrap: anywhere;
}

.account-identity small {
  font-size: 12px;
  color: #64776f;
}

.account-options a {
  display: block;
  color: #173b36;
  text-decoration: none;
  font-size: 13px;
  padding: 12px;
}

.account-options a:hover {
  background: #eef1e8;
}

.account-options {
  top: 100%;
  max-height: 75vh;
  overflow: auto;
  z-index: 40;
}

@media (max-width: 480px) {
  .account-identity {
    max-width: 145px;
    font-size: 12px;
  }
}
.menu-heading {
  display: block;
  padding: 10px 12px 4px;
  font-size: 11px;
  color: #64776f;
  border-top: 1px solid #e4eae5;
}

.platform-controls {
  flex-wrap: wrap;
  justify-content: flex-end;
}

.account-options {
  min-width: 230px;
}

@media (max-width: 600px) {
  .platform-controls .account-identity {
    flex-basis: 100%;
    max-width: none;
  }
}
.workspace-view-switch {
  border: 1px solid #94aaa0;
  border-radius: 999px;
  background: white;
  color: #173b36;
  padding: 9px 13px;
  font: inherit;
  font-size: 12px;
  cursor: pointer;
}

.workspace-view-switch:disabled {
  opacity: 0.55;
}

.account-identity strong {
  display: block;
  color: #173b36;
  font-size: 14px;
  font-weight: 700;
}

.account-identity {
  display: flex !important;
  visibility: visible !important;
  flex-direction: column;
  gap: 2px;
  overflow-wrap: anywhere;
}

.account-identity small {
  font-size: 11px;
}

@media (max-width: 600px) {
  .workspace-view-switch {
    padding: 8px;
    font-size: 11px;
  }
