  display: block;
  background: #f6f7f1;
  min-height: 100vh;
}

.publication-dialog {
  width: min(480px, 100vw - 32px);
  max-height: calc(100dvh - 40px);
  overflow: auto;
  border: 1px solid #dce5df;
  border-radius: 22px;
  padding: 36px;
  color: #173b36;
  background: #fffdf8;
  font-family: Inter, "Segoe UI", Arial, sans-serif;
  box-shadow: 0 22px 75px rgba(23, 59, 54, 0.2);
}

.publication-dialog::backdrop {
  background: rgba(16, 45, 40, 0.6509803922);
}

.publication-close {
  position: absolute;
  right: 16px;
  top: 12px;
  border: 0;
  background: transparent;
  color: #173b36;
  font-size: 27px;
  cursor: pointer;
}

.publication-brand {
  font-size: 18px;
  font-weight: 750;
}

.publication-dialog h2 {
  font: 400 31px/1.2 Georgia, serif;
  margin: 24px 0 14px;
}

.publication-dialog p {
  font-size: 14px;
  line-height: 1.7;
  color: #64776f;
}

.publication-actions {
  display: grid;
  gap: 12px;
  margin: 26px 0 18px;
}

.publication-actions button {
  padding: 14px 18px;
  border: 1px solid #173b36;
  border-radius: 100px;
  background: #173b36;
  color: white;
  font: 600 14px Inter, Arial, sans-serif;
  cursor: pointer;
}

.publication-actions button + button {
  background: transparent;
  color: #173b36;
}

.publication-cancel {
  display: block;
  margin: auto;
  border: 0;
  background: transparent;
  color: #64776f;
  font: 13px Inter, Arial, sans-serif;
  cursor: pointer;
}

.publication-dialog button:focus-visible {
  outline: 3px solid #7fac61;
  outline-offset: 4px;
}

@media (max-width: 480px) {
  .publication-dialog {
    padding: 28px 23px;
  }
  .publication-dialog h2 {
    font-size: 28px;
  }
}
.account-identity {
  display: flex;
  flex-direction: column;
  text-align: right;
  max-width: 230px;
  font-size: 13px;
  overflow-wrap: anywhere;
  margin-left: auto;
}

.account-identity small {
  font-size: 12px;
  color: #64776f;
}

.account-menu {
  margin-left: 8px;
}

.account-panel {
  max-height: 75vh;
  overflow: auto;
}

.account-panel a[href="#rentals"] {
  display: block;
  padding: 12px;
}

@media (max-width: 600px) {
  .account-identity {
    max-width: 140px;
    font-size: 12px;
  }
}
.registry-page .account-text {
  display: inline;
}

.registry-page .language-switch {
  margin-left: auto;
}

.registry-page .account-identity {
  margin-left: 0;
}

@media (max-width: 440px) {
  .registry-page .site-header {
    height: auto;
    min-height: 76px;
    flex-wrap: wrap;
    padding-top: 12px;
    padding-bottom: 12px;
  }
}
.registry-page .site-header {
  height: auto;
  min-height: 90px;
  flex-wrap: wrap;
  padding-top: 12px;
  padding-bottom: 12px;
}

.account-panel strong {
  display: block;
  padding: 10px;
  font-size: 12px;
  border-top: 1px solid #ddd;
}

.account-menu summary {
  white-space: nowrap;
}

@media (max-width: 600px) {
  .registry-page .account-identity {
    max-width: none;
    flex-basis: 100%;
  }
}
.workspace-view-switch {
  border: 1px solid #94aaa0;
  border-radius: 999px;
  background: white;
  color: #173b36;
  padding: 9px 13px;
  font: inherit;
  font-size: 12px;
  cursor: pointer;
}

.workspace-view-switch:disabled {
  opacity: 0.55;
}

.account-identity strong {
  display: block;
  color: #173b36;
  font-size: 14px;
  font-weight: 700;
}

.account-identity {
  display: flex !important;
  visibility: visible !important;
  flex-direction: column;
  gap: 2px;
  overflow-wrap: anywhere;
}

.account-identity small {
  font-size: 11px;
}

@media (max-width: 600px) {
  .workspace-view-switch {
    padding: 8px;
    font-size: 11px;
  }
