  display: block;
  color: #103f68;
  font-family: Inter, "Segoe UI", Arial, sans-serif;
}

.concierge-pitch, .role-guide {
  max-width: 1296px;
  margin: 0 auto 64px;
  scroll-margin-top: 30px;
}

.concierge-pitch {
  background: #103f68;
  color: #f6f8ef;
  border-radius: 24px;
  padding: 58px 5vw;
  display: grid;
  grid-template-columns: minmax(0, 1.5fr) minmax(240px, 1fr);
  gap: 44px;
  overflow: hidden;
}

.eyebrow {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  font-weight: 650;
}

.concierge-pitch h2 {
  font: 400 clamp(32px, 3.4vw, 48px)/1.15 Georgia, serif;
  max-width: 620px;
  margin: 20px 0;
}

.pitch-intro {
  font-size: 14px;
  line-height: 1.85;
  color: #d2e0e5;
  max-width: 600px;
}

.pitch-actions {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 18px;
  margin-top: 28px;
}

.journey-cta {
  display: inline-block;
  border: 0;
  border-radius: 11px;
  padding: 14px 21px;
  font: 600 13px/1.4 Inter, "Segoe UI", Arial, sans-serif;
  text-decoration: none;
  cursor: pointer;
}

.journey-cta.light {
  background: #e5edbc;
  color: #103f68;
}

.journey-cta.dark {
  background: #103f68;
  color: white;
}

.explore {
  border: 0;
  border-bottom: 1px solid #b4c7d1;
  background: transparent;
  color: #f6f8ef;
  padding: 8px 0;
  cursor: pointer;
  font: inherit;
  font-size: 13px;
}

.portfolio-art {
  position: relative;
  min-height: 260px;
  align-self: center;
}

.portfolio-card {
  position: absolute;
  width: 80%;
  max-width: 290px;
  padding: 23px;
  border-radius: 16px;
  background: #f9fbf4;
  color: #103f68;
  box-shadow: 0 15px 35px rgba(0, 27, 48, 0.2);
}

.owner-card {
  top: 0;
  left: 0;
  transform: rotate(-7deg);
}

.concierge-card {
  right: 0;
  bottom: 0;
  transform: rotate(5deg);
  background: #e5edbc;
}

.portfolio-card strong {
  font-size: 13px;
}

.card-dot {
  display: inline-block;
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: #50764d;
  margin-right: 9px;
}

.asset-symbols {
  font-size: 25px;
  margin-top: 20px;
  white-space: nowrap;
}

.portfolio-lines {
  display: grid;
  gap: 7px;
  margin-top: 18px;
}

.portfolio-lines span {
  height: 5px;
  background: rgba(16, 63, 104, 0.1254901961);
  border-radius: 5px;
}

.portfolio-lines span:nth-child(2) {
  width: 75%;
}

.portfolio-lines span:nth-child(3) {
  width: 50%;
}

.role-guide {
  padding: 0 2vw;
}

.role-guide > header {
  max-width: 700px;
  margin-bottom: 30px;
}

.role-guide h2 {
  font: 400 clamp(29px, 3vw, 40px)/1.2 Georgia, serif;
  margin-bottom: 15px;
}

.role-guide > header p {
  line-height: 1.8;
  color: #526b80;
  font-size: 14px;
}

.role-choices {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
  margin-bottom: 20px;
}

.role-choices button {
  border: 1px solid #dbe5ed;
  border-radius: 12px;
  background: white;
  padding: 15px 10px;
  color: #103f68;
  font: 600 13px/1.4 Inter, "Segoe UI", Arial, sans-serif;
  cursor: pointer;
}

.role-choices button.selected {
  background: #e5edbc;
  border-color: #a7b777;
}

.role-journey {
  display: grid;
  grid-template-columns: 1fr 1fr;
  border: 1px solid #dbe5ed;
  border-radius: 18px;
  background: white;
  overflow: hidden;
}

.role-summary, .role-process {
  padding: 34px;
}

.role-summary h3 {
  font: 400 29px/1.25 Georgia, serif;
  margin: 15px 0;
}

.role-summary > p:not(.eyebrow) {
  font-size: 14px;
  line-height: 1.8;
  color: #526b80;
}

.role-summary h4, .role-process h4 {
  font-size: 14px;
  margin: 25px 0 16px;
}

.role-summary ul {
  padding-left: 20px;
  margin: 0 0 24px;
}

.role-summary li {
  font-size: 13px;
  line-height: 1.8;
  padding-left: 4px;
  margin-bottom: 8px;
}

.role-process {
  background: #f2f6f7;
}

.role-process h4 {
  margin-top: 0;
}

.role-process ol {
  list-style: none;
  padding: 0;
  margin: 0;
  display: grid;
  gap: 25px;
}

.role-process li {
  display: flex;
  gap: 17px;
}

.step-number {
  font: 400 28px Georgia, serif;
  color: #597a85;
}

.role-process li p {
  font-size: 13px;
  line-height: 1.8;
  margin: 0;
}

.delegation-note, .account-note {
  color: #526b80;
  font-size: 12px;
  line-height: 1.8;
  margin: 17px 0 0;
}

.role-note {
  font-size: 12px !important;
}

.journey-cta[hidden] {
  display: none !important;
}

button:focus-visible, a:focus-visible {
  outline: 3px solid #b36d25;
  outline-offset: 4px;
}

@media (max-width: 1100px) {
  .concierge-pitch, .role-guide {
    margin-left: 5vw;
    margin-right: 5vw;
  }
  .concierge-pitch {
    gap: 25px;
    padding: 40px 30px;
  }
  .role-summary, .role-process {
    padding: 26px;
  }
}
@media (max-width: 720px) {
  .concierge-pitch {
    grid-template-columns: 1fr;
    padding: 34px 25px;
  }
  .portfolio-art {
    display: none;
  }
  .role-guide {
    padding: 0;
  }
  .role-choices {
    grid-template-columns: repeat(2, 1fr);
  }
  .role-journey {
    grid-template-columns: 1fr;
  }
  .role-summary, .role-process {
    padding: 25px;
  }
  .pitch-actions {
    align-items: flex-start;
    flex-direction: column;
  }
  .role-guide h2 {
    font-size: 31px;
  }
  .concierge-pitch, .role-guide {
    margin-bottom: 42px;
  }
}
